const CATEGORIES = ['All', 'Story', 'Comic', 'Writing', 'Sequence', 'Thinking'];
const WorksheetMaker = () => {
  const [selectedTemplate, setSelectedTemplate] = useState(null);
  const [activeCategory, setActiveCategory] = useState('All');
  const [zoom, setZoom] = useState(100);
  const [elementData, setElementData] = useState({});
  const [snackbar, setSnackbar] = useState({ open: false, message: '', severity: 'success' });
  const [leftTab, setLeftTab] = useState(0);
  // History for undo/redo
  const [history, setHistory] = useState([]);
  const [historyIndex, setHistoryIndex] = useState(-1);
  // Save/Load
  const [saveDialog, setSaveDialog] = useState(false);
  const [templateName, setTemplateName] = useState('');
  const [savedTemplates, setSavedTemplates] = useState([]);
  const [customTemplates, setCustomTemplates] = useState([]);
  const [editingTemplate, setEditingTemplate] = useState(null);
  // Color picker
  const [colorAnchor, setColorAnchor] = useState(null);
  const [colorTarget, setColorTarget] = useState(null);
  const canvasRef = useRef(null);
  const fileInputRef = useRef(null);
  const dropTargetRef = useRef(null);
  // Load saved data
  useEffect(() => {
    const saved = JSON.parse(localStorage.getItem('worksheetMakerList') || '[]');
    setSavedTemplates(saved);
    const custom = JSON.parse(localStorage.getItem('worksheetCustomTemplates') || '[]');
    setCustomTemplates(custom);
  }, []);
  // Filter templates - include saved designs as templates
  const allTemplates = [...WORKSHEET_TEMPLATES, ...customTemplates, ...savedTemplates.map(s => ({
    ...s.template,
    id: `saved-${s.name}`,
    name: `📁 ${s.name}`,
    isSaved: true,
    savedData: s
  }))];
  const filteredTemplates = activeCategory === 'All' 
    ? allTemplates
    : allTemplates.filter(t => t.category === activeCategory || t.isSaved);
  // Save to history
  const saveToHistory = useCallback((data) => {
    const newHistory = history.slice(0, historyIndex + 1);
    newHistory.push(JSON.stringify(data));
    setHistory(newHistory);
    setHistoryIndex(newHistory.length - 1);
  }, [history, historyIndex]);
  // Undo/Redo
  const handleUndo = () => {
    if (historyIndex > 0) {
      setHistoryIndex(historyIndex - 1);
      setElementData(JSON.parse(history[historyIndex - 1]));
    }
  };
  const handleRedo = () => {
    if (historyIndex < history.length - 1) {
      setHistoryIndex(historyIndex + 1);
      setElementData(JSON.parse(history[historyIndex + 1]));
    }
  };
  // Handle template selection
  const handleSelectTemplate = (template) => {
    if (template.isSaved && template.savedData) {
      // Load saved design
      setSelectedTemplate(template.savedData.template);
      setElementData(template.savedData.data || {});
    } else {
      setSelectedTemplate(template);
      setElementData({});
    }
    setHistory([]);
    setHistoryIndex(-1);
  };
  // Handle image upload with auto-fit
  const handleImageUpload = (elementId, event) => {
    const file = event.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (e) => {
        const newData = { ...elementData, [elementId]: { ...elementData[elementId], image: e.target.result } };
        setElementData(newData);
        saveToHistory(newData);
      };
      reader.readAsDataURL(file);
    }
  };
  // Handle dropping image from sidebar
  const handleDropImage = (elementId, imageUrl) => {
    const newData = { ...elementData, [elementId]: { ...elementData[elementId], image: imageUrl } };
    setElementData(newData);
    saveToHistory(newData);
    setSnackbar({ open: true, message: 'Image added!', severity: 'success' });
  };
  // Handle text change
  const handleTextChange = (elementId, text) => {
    const newData = { ...elementData, [elementId]: { ...elementData[elementId], text } };
    setElementData(newData);
  };
  // Handle text blur (save to history)
  const handleTextBlur = () => {
    saveToHistory(elementData);
  };
  // Export
  const handleExport = async () => {
    if (!canvasRef.current) return;
    try {
      const canvas = await html2canvas(canvasRef.current, { scale: 2, backgroundColor: '#fff' });
      const link = document.createElement('a');
      link.download = `worksheet-${Date.now()}.png`;
      link.href = canvas.toDataURL();
      link.click();
      setSnackbar({ open: true, message: 'Exported!', severity: 'success' });
    } catch (error) {
      setSnackbar({ open: true, message: 'Export failed', severity: 'error' });
    }
  };
  // Save with name
  const handleSave = () => {
    if (!templateName.trim()) {
      setSnackbar({ open: true, message: 'Please enter a name', severity: 'error' });
      return;
    }
    if (!selectedTemplate) return;
    const saved = {
      id: editingTemplate?.id || Date.now(),
      name: templateName,
      template: selectedTemplate,
      data: elementData,
      savedAt: new Date().toISOString()
    };
    let newList;
    if (editingTemplate) {
      newList = savedTemplates.map(s => s.id === editingTemplate.id ? saved : s);
    } else {
      newList = [...savedTemplates.filter(s => s.name !== templateName), saved];
    }
    localStorage.setItem('worksheetMakerList', JSON.stringify(newList));
    setSavedTemplates(newList);
    setSaveDialog(false);
    setTemplateName('');
    setEditingTemplate(null);
    setSnackbar({ open: true, message: `"${templateName}" saved!`, severity: 'success' });
  };
  // Load saved
  const handleLoad = (saved) => {
    setSelectedTemplate(saved.template);
    setElementData(saved.data || {});
    setSnackbar({ open: true, message: `Loaded "${saved.name}"`, severity: 'success' });
  };
  // Edit saved template
  const handleEditSaved = (saved) => {
    setEditingTemplate(saved);
    setTemplateName(saved.name);
    setSaveDialog(true);
  };
  // Delete saved
  const handleDeleteSaved = (id) => {
    const newList = savedTemplates.filter(s => s.id !== id && s.name !== id);
    localStorage.setItem('worksheetMakerList', JSON.stringify(newList));
    setSavedTemplates(newList);
    setSnackbar({ open: true, message: 'Deleted', severity: 'info' });
  };
  // Delete custom template
  const handleDeleteCustomTemplate = (id) => {
    const newList = customTemplates.filter(t => t.id !== id);
    localStorage.setItem('worksheetCustomTemplates', JSON.stringify(newList));
    setCustomTemplates(newList);
    setSnackbar({ open: true, message: 'Template deleted', severity: 'info' });
  };
  // Save as custom template
  const handleSaveAsTemplate = () => {
    if (!templateName.trim() || !selectedTemplate) return;
    const newTemplate = {
      ...selectedTemplate,
      id: Date.now(),
      name: templateName,
      isCustom: true
    };
    const newList = [...customTemplates, newTemplate];
    localStorage.setItem('worksheetCustomTemplates', JSON.stringify(newList));
    setCustomTemplates(newList);
    setSaveDialog(false);
    setTemplateName('');
    setSnackbar({ open: true, message: 'Custom template saved!', severity: 'success' });
  };
  // Render element
  const renderElement = (element) => {
    const data = elementData[element.id] || {};
    const style = {
      position: 'absolute',
      left: `${element.x}%`,
      top: `${element.y}%`,
      width: `${element.width}%`,
      height: `${element.height}%`,
    };
    switch (element.type) {
      case 'frame':
        return (
          <Box
            key={element.id}
            onDragOver={(e) => { e.preventDefault(); dropTargetRef.current = element.id; }}
            onDrop={(e) => {
              e.preventDefault();
              const imageUrl = e.dataTransfer.getData('imageUrl');
              if (imageUrl) handleDropImage(element.id, imageUrl);
            }}
            sx={{
              ...style,
              border: element.border || '2px solid #333',
              borderRadius: element.shape === 'circle' ? '50%' : 1,
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              backgroundColor: data.image ? 'transparent' : '#f9f9f9',
              backgroundImage: data.image ? `url(${data.image})` : 'none',
              backgroundSize: 'cover',
              backgroundPosition: 'center',
              cursor: 'pointer',
              overflow: 'hidden',
              '&:hover': { borderColor: '#1976d2', boxShadow: 2 }
            }}
            onClick={() => {
              const input = document.createElement('input');
              input.type = 'file';
              input.accept = 'image/*';
              input.onchange = (e) => handleImageUpload(element.id, e);
              input.click();
            }}
          >
            {!data.image && (
              <Box sx={{ textAlign: 'center', color: '#999' }}>
                <ImageIcon sx={{ fontSize: 24 }} />
                <Typography variant="caption" display="block">{element.label || 'Add image'}</Typography>
              </Box>
            )}
          </Box>
        );
      case 'textarea':
        return (
          <Box key={element.id} sx={{ ...style }}>
            <textarea
              style={{
                width: '100%',
                height: '100%',
                border: '1px solid #ddd',
                borderRadius: 4,
                padding: 8,
                fontSize: 12,
                resize: 'none',
                fontFamily: 'inherit',
                backgroundColor: 'rgba(255,255,255,0.9)'
              }}
              value={data.text || ''}
              onChange={(e) => handleTextChange(element.id, e.target.value)}
              onBlur={handleTextBlur}
              placeholder={element.placeholder}
            />
          </Box>
        );
      case 'lined':
        return (
          <Box key={element.id} sx={{ ...style, position: 'relative' }}>
            <Box sx={{ position: 'absolute', inset: 0, p: 0.5, backgroundColor: 'rgba(255,255,255,0.8)', borderRadius: 1 }}>
              {Array.from({ length: element.lines || 5 }).map((_, i) => (
                <Box key={i} sx={{ borderBottom: '1px solid #ccc', height: `${100 / element.lines}%` }} />
              ))}
            </Box>
            <textarea
              style={{
                position: 'absolute',
                inset: 0,
                width: '100%',
                height: '100%',
                border: 'none',
                background: 'transparent',
                resize: 'none',
                padding: 4,
                fontSize: 11,
                lineHeight: `${100 / element.lines / 3}px`,
                fontFamily: 'inherit'
              }}
              value={data.text || ''}
              onChange={(e) => handleTextChange(element.id, e.target.value)}
              onBlur={handleTextBlur}
              placeholder="Write here..."
            />
          </Box>
        );
      case 'title':
        return (
          <Box key={element.id} sx={{ ...style, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
            <input
              type="text"
              style={{
                width: '100%',
                textAlign: 'center',
                fontWeight: 'bold',
                fontSize: 18,
                border: 'none',
                background: 'transparent',
                fontFamily: 'inherit'
              }}
              value={data.text ?? element.text ?? ''}
              onChange={(e) => handleTextChange(element.id, e.target.value)}
              onBlur={handleTextBlur}
            />
          </Box>
        );
      case 'label':
        return (
          <Box key={element.id} sx={{ ...style, display: 'flex', alignItems: 'center', justifyContent: 'center', backgroundColor: '#e3f2fd', borderRadius: 1 }}>
            <Typography variant="caption" sx={{ fontWeight: 'bold', textAlign: 'center' }}>
              {element.text}
            </Typography>
          </Box>
        );
      case 'line':
        return <Box key={element.id} sx={{ ...style, backgroundColor: '#333', borderRadius: 1 }} />;
      case 'arrow':
        return (
          <Box key={element.id} sx={{ ...style, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
            <Typography sx={{ fontSize: 28, fontWeight: 'bold' }}>→</Typography>
          </Box>
        );
      default:
        return null;
    }
  };
  return (
    <Box sx={{ display: 'flex', height: 'calc(100vh - 80px)', bgcolor: '#f0f2f5' }}>
      {/* Left Sidebar */}
      <Paper sx={{ width: 280, display: 'flex', flexDirection: 'column', borderRadius: 0 }}>
        <Tabs value={leftTab} onChange={(e, v) => setLeftTab(v)} variant="fullWidth">
          <Tab label="Templates" sx={{ fontSize: '0.75rem' }} />
          <Tab label="Images" sx={{ fontSize: '0.75rem' }} />
        </Tabs>
        {leftTab === 0 && (
          <Box sx={{ flex: 1, overflow: 'auto', p: 1 }}>
            <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 0.5, mb: 1 }}>
              {CATEGORIES.map(cat => (
                <Chip
                  key={cat}
                  label={cat}
                  size="small"
                  onClick={() => setActiveCategory(cat)}
                  color={activeCategory === cat ? 'primary' : 'default'}
                  variant={activeCategory === cat ? 'filled' : 'outlined'}
                  sx={{ fontSize: '0.65rem' }}
                />
              ))}
            </Box>
            <Grid container spacing={1}>
              {filteredTemplates.map(template => (
                <Grid item xs={6} key={template.id}>
                  <Card
                    sx={{
                      cursor: 'pointer',
                      border: selectedTemplate?.id === template.id ? '2px solid #1976d2' : '1px solid #e0e0e0',
                      position: 'relative',
                      '&:hover': { boxShadow: 3 },
                      '&:hover .template-actions': { opacity: 1 }
                    }}
                    onClick={() => handleSelectTemplate(template)}
                  >
                    <Box sx={{ height: 60, background: template.bgGradient || template.bgColor }} />
                    <CardContent sx={{ p: 0.5, '&:last-child': { pb: 0.5 } }}>
                      <Typography variant="caption" noWrap sx={{ fontSize: '0.65rem' }}>
                        {template.name} {template.isCustom && '⭐'}
                      </Typography>
                    </CardContent>
                    {/* Edit/Delete buttons for custom templates and saved designs */}
                    {(template.isCustom || template.isSaved) && (
                      <Box className="template-actions" sx={{ position: 'absolute', top: 2, right: 2, opacity: 0, transition: 'opacity 0.2s', display: 'flex', gap: 0.25 }}>
                        {template.isSaved && (
                          <IconButton size="small" sx={{ backgroundColor: 'rgba(255,255,255,0.9)', p: 0.25 }}
                            onClick={(e) => { e.stopPropagation(); handleEditSaved(template.savedData); }}>
                            <EditIcon sx={{ fontSize: 14 }} />
                          </IconButton>
                        )}
                        <IconButton size="small" sx={{ backgroundColor: 'rgba(255,255,255,0.9)', p: 0.25 }}
                          onClick={(e) => { e.stopPropagation(); 
                            template.isSaved ? handleDeleteSaved(template.savedData.id) : handleDeleteCustomTemplate(template.id); }}>
                          <DeleteIcon sx={{ fontSize: 14 }} />
                        </IconButton>
                      </Box>
                    )}
                  </Card>
                </Grid>
              ))}
            </Grid>
          </Box>
        )}
        {leftTab === 1 && (
          <Box sx={{ flex: 1, overflow: 'auto', p: 1 }}>
            <Typography variant="caption" color="text.secondary" sx={{ mb: 1, display: 'block' }}>
              Drag images to frames
            </Typography>
            <Grid container spacing={1}>
              {SAMPLE_IMAGES.map((img, idx) => (
                <Grid item xs={4} key={idx}>
                  <Box
                    component="img"
                    src={img}
                    draggable
                    onDragStart={(e) => e.dataTransfer.setData('imageUrl', img)}
                    sx={{
                      width: '100%',
                      height: 60,
                      objectFit: 'cover',
                      borderRadius: 1,
                      cursor: 'grab',
                      '&:hover': { opacity: 0.8 }
                    }}
                  />
                </Grid>
              ))}
            </Grid>
            <Divider sx={{ my: 1 }} />
            <Button
              size="small"
              variant="outlined"
              fullWidth
              onClick={() => fileInputRef.current?.click()}
            >
              Upload Image
            </Button>
            <input
              ref={fileInputRef}
              type="file"
              accept="image/*"
              hidden
              onChange={(e) => {
                const file = e.target.files?.[0];
                if (file && dropTargetRef.current) {
                  handleImageUpload(dropTargetRef.current, e);
                }
              }}
            />
          </Box>
        )}
      </Paper>
      {/* Main Canvas Area */}
      <Box sx={{ flex: 1, display: 'flex', flexDirection: 'column' }}>
        {/* Toolbar */}
        <Paper sx={{ p: 1, borderRadius: 0, display: 'flex', alignItems: 'center', gap: 1, flexWrap: 'wrap' }}>
          <Tooltip title="Undo"><span><IconButton onClick={handleUndo} disabled={historyIndex <= 0} size="small"><UndoIcon /></IconButton></span></Tooltip>
          <Tooltip title="Redo"><span><IconButton onClick={handleRedo} disabled={historyIndex >= history.length - 1} size="small"><RedoIcon /></IconButton></span></Tooltip>
          <Divider orientation="vertical" flexItem />
          <Tooltip title="Zoom Out"><IconButton onClick={() => setZoom(Math.max(50, zoom - 10))} size="small"><ZoomOutIcon /></IconButton></Tooltip>
          <Typography sx={{ minWidth: 45, textAlign: 'center', fontSize: '0.8rem' }}>{zoom}%</Typography>
          <Tooltip title="Zoom In"><IconButton onClick={() => setZoom(Math.min(200, zoom + 10))} size="small"><ZoomInIcon /></IconButton></Tooltip>
          <Divider orientation="vertical" flexItem />
          <Button size="small" startIcon={<SaveIcon />} onClick={() => setSaveDialog(true)} disabled={!selectedTemplate}>Save</Button>
          <Button size="small" startIcon={<LoadIcon />} onClick={() => setLoadDialog(true)}>Load</Button>
          <Button size="small" startIcon={<DownloadIcon />} onClick={handleExport} disabled={!selectedTemplate}>Export</Button>
          <Button size="small" startIcon={<PrintIcon />} onClick={() => window.print()} disabled={!selectedTemplate}>Print</Button>
        </Paper>
        {/* Canvas */}
        <Box sx={{ flex: 1, overflow: 'auto', display: 'flex', justifyContent: 'center', alignItems: 'center', p: 2 }}>
          {selectedTemplate ? (
            <Paper
              ref={canvasRef}
              sx={{
                width: 595 * (zoom / 100),
                height: 842 * (zoom / 100),
                position: 'relative',
                backgroundColor: selectedTemplate.bgColor || '#fff',
                boxShadow: 3
              }}
            >
              {selectedTemplate.elements?.map(el => renderElement(el))}
            </Paper>
          ) : (
            <Box sx={{ textAlign: 'center', color: '#999' }}>
              <Typography variant="h6">Select a template to get started</Typography>
              <Typography variant="body2">Choose from {WORKSHEET_TEMPLATES.length} templates</Typography>
            </Box>
          )}
        </Box>
      </Box>
      {/* Save Dialog */}
      <Dialog open={saveDialog} onClose={() => setSaveDialog(false)}>
        <DialogTitle>Save Worksheet</DialogTitle>
        <DialogContent>
          <TextField
            autoFocus
            margin="dense"
            label="Name"
            fullWidth
            value={templateName}
            onChange={(e) => setTemplateName(e.target.value)}
            placeholder="e.g., My Story Board"
          />
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setSaveDialog(false)}>Cancel</Button>
          <Button onClick={handleSaveAsTemplate} variant="outlined">Save as Template</Button>
          <Button onClick={handleSave} variant="contained">Save Work</Button>
        </DialogActions>
      </Dialog>
      <Snackbar open={snackbar.open} autoHideDuration={3000} onClose={() => setSnackbar({ ...snackbar, open: false })}>
        <Alert severity={snackbar.severity}>{snackbar.message}</Alert>
      </Snackbar>
    </Box>
  );
};
export default WorksheetMaker;
