import { createSlice, createAsyncThunk } from "@reduxjs/toolkit";
import axios from "axios";
export const SearchImages = createAsyncThunk(
    'search/global',
    async (data, { rejectWithValue }) => {
        try {
            let response = await axios.request({
                baseURL: process.env.REACT_APP_BACKEND_URL + "/api",
                url: '/rest/search/global',
                method: "GET",
                headers: {"Content-Type": "application/json"},
                params : data?.body
            })
            return response.data
        } catch (err) {
            return rejectWithValue(err.response.data);
        }
    }
);
const fetchSearchSlice = createSlice({
    name: "searchedImage",
    initialState: {
        searchedImages: [],
        hasMore: false,
        pagination : 0,
        msg: null,
        loading: false,
    },
    reducers: {},
    extraReducers: (builder) => {
        builder
            .addCase(SearchImages.fulfilled, (state, { payload }) => {
                state.images = payload
                state.searchedImages = payload.data
                state.pagination = Math.ceil(payload.total/payload.length)
                state.hasMore = payload.hasMore
                state.loading = false;
            })
            .addCase(SearchImages.pending, (state) => {
                state.loading = true;
            })
            .addCase(SearchImages.rejected, (state) => {
                state.loading = false;
            })
    }
})
export default fetchSearchSlice.reducer;