const CATEGORIES = [
  { name: 'All', icon: <StarIcon /> },
  { name: 'Family', icon: <FamilyIcon /> },
  { name: 'Pets', icon: <PetsIcon /> },
  { name: 'Seasonal', icon: <SeasonIcon /> },
  { name: 'Kids', icon: <KidsIcon /> }
];
const StoryMaker = () => {
  const [selectedTemplate, setSelectedTemplate] = useState(null);
  const [activeCategory, setActiveCategory] = useState('All');
  const [zoom, setZoom] = useState(100);
  const [frameData, setFrameData] = useState({});
  const [snackbar, setSnackbar] = useState({ open: false, message: '', severity: 'success' });
  const [leftTab, setLeftTab] = useState(0);
  // History
  const [history, setHistory] = useState([]);
  const [historyIndex, setHistoryIndex] = useState(-1);
  // Save/Load
  const [saveDialog, setSaveDialog] = useState(false);
  const [storyName, setStoryName] = useState('');
  const [savedStories, setSavedStories] = useState([]);
  const [customTemplates, setCustomTemplates] = useState([]);
  const [editingTemplate, setEditingTemplate] = useState(null);
  const canvasRef = useRef(null);
  const dropTargetRef = useRef(null);
  // Load saved data
  useEffect(() => {
    const saved = JSON.parse(localStorage.getItem('storyMakerList') || '[]');
    setSavedStories(saved);
    const custom = JSON.parse(localStorage.getItem('storyCustomTemplates') || '[]');
    setCustomTemplates(custom);
  }, []);
  // Include saved stories as templates
  const allTemplates = [...STORY_TEMPLATES, ...customTemplates, ...savedStories.map(s => ({
    ...s.template,
    id: `saved-${s.name}`,
    name: `📁 ${s.name}`,
    isSaved: true,
    savedData: s
  }))];
  const filteredTemplates = activeCategory === 'All'
    ? allTemplates
    : allTemplates.filter(t => t.category === activeCategory || t.isSaved);
  // Save to history
  const saveToHistory = useCallback((data) => {
    const newHistory = history.slice(0, historyIndex + 1);
    newHistory.push(JSON.stringify(data));
    setHistory(newHistory);
    setHistoryIndex(newHistory.length - 1);
  }, [history, historyIndex]);
  // Undo/Redo
  const handleUndo = () => {
    if (historyIndex > 0) {
      setHistoryIndex(historyIndex - 1);
      setFrameData(JSON.parse(history[historyIndex - 1]));
    }
  };
  const handleRedo = () => {
    if (historyIndex < history.length - 1) {
      setHistoryIndex(historyIndex + 1);
      setFrameData(JSON.parse(history[historyIndex + 1]));
    }
  };
  const handleSelectTemplate = (template) => {
    if (template.isSaved && template.savedData) {
      setSelectedTemplate(template.savedData.template);
      setFrameData(template.savedData.data || {});
    } else {
      setSelectedTemplate(template);
      setFrameData({});
    }
    setHistory([]);
    setHistoryIndex(-1);
  };
  // Image upload with auto-fit
  const handleImageUpload = (frameId, event) => {
    const file = event.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (e) => {
        const newData = { ...frameData, [frameId]: { ...frameData[frameId], image: e.target.result } };
        setFrameData(newData);
        saveToHistory(newData);
      };
      reader.readAsDataURL(file);
    }
  };
  // Drag & drop image
  const handleDropImage = (frameId, imageUrl) => {
    const newData = { ...frameData, [frameId]: { ...frameData[frameId], image: imageUrl } };
    setFrameData(newData);
    saveToHistory(newData);
    setSnackbar({ open: true, message: 'Image added!', severity: 'success' });
  };
  const handleTextChange = (frameId, text) => {
    const newData = { ...frameData, [frameId]: { ...frameData[frameId], text } };
    setFrameData(newData);
  };
  const handleTextBlur = () => {
    saveToHistory(frameData);
  };
  const handleExport = async () => {
    if (!canvasRef.current) return;
    try {
      const canvas = await html2canvas(canvasRef.current, { scale: 2, backgroundColor: selectedTemplate?.bgColor || '#fff' });
      const link = document.createElement('a');
      link.download = `story-${Date.now()}.png`;
      link.href = canvas.toDataURL();
      link.click();
      setSnackbar({ open: true, message: 'Exported!', severity: 'success' });
    } catch (error) {
      setSnackbar({ open: true, message: 'Export failed', severity: 'error' });
    }
  };
  // Save with name
  const handleSave = () => {
    if (!storyName.trim()) {
      setSnackbar({ open: true, message: 'Please enter a name', severity: 'error' });
      return;
    }
    if (!selectedTemplate) return;
    const saved = {
      id: editingTemplate?.id || Date.now(),
      name: storyName,
      template: selectedTemplate,
      data: frameData,
      savedAt: new Date().toISOString()
    };
    let newList;
    if (editingTemplate) {
      newList = savedStories.map(s => s.id === editingTemplate.id ? saved : s);
    } else {
      newList = [...savedStories.filter(s => s.name !== storyName), saved];
    }
    localStorage.setItem('storyMakerList', JSON.stringify(newList));
    setSavedStories(newList);
    setSaveDialog(false);
    setStoryName('');
    setEditingTemplate(null);
    setSnackbar({ open: true, message: `"${storyName}" saved!`, severity: 'success' });
  };
  const handleLoad = (saved) => {
    setSelectedTemplate(saved.template);
    setFrameData(saved.data || {});
    setSnackbar({ open: true, message: `Loaded "${saved.name}"`, severity: 'success' });
  };
  const handleEditSaved = (saved) => {
    setEditingTemplate(saved);
    setStoryName(saved.name);
    setSaveDialog(true);
  };
  const handleDeleteSaved = (id) => {
    const newList = savedStories.filter(s => s.id !== id && s.name !== id);
    localStorage.setItem('storyMakerList', JSON.stringify(newList));
    setSavedStories(newList);
    setSnackbar({ open: true, message: 'Deleted', severity: 'info' });
  };
  const handleDeleteCustomTemplate = (id) => {
    const newList = customTemplates.filter(t => t.id !== id);
    localStorage.setItem('storyCustomTemplates', JSON.stringify(newList));
    setCustomTemplates(newList);
    setSnackbar({ open: true, message: 'Template deleted', severity: 'info' });
  };
  // Save as custom template
  const handleSaveAsTemplate = () => {
    if (!storyName.trim() || !selectedTemplate) return;
    const newTemplate = {
      ...selectedTemplate,
      id: Date.now(),
      name: storyName,
      isCustom: true
    };
    const newList = [...customTemplates, newTemplate];
    localStorage.setItem('storyCustomTemplates', JSON.stringify(newList));
    setCustomTemplates(newList);
    setSaveDialog(false);
    setStoryName('');
    setSnackbar({ open: true, message: 'Custom template saved!', severity: 'success' });
  };
  // Render frame
  const renderFrame = (frame) => {
    const data = frameData[frame.id] || {};
    const style = {
      position: 'absolute',
      left: `${frame.x}%`,
      top: `${frame.y}%`,
      width: `${frame.width}%`,
      height: `${frame.height}%`,
    };
    if (frame.type === 'text') {
      return (
        <Box key={frame.id} sx={{ ...style, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
          <input
            type="text"
            style={{
              width: '100%',
              textAlign: 'center',
              fontWeight: 'bold',
              fontSize: 14,
              border: 'none',
              background: 'transparent',
              fontFamily: 'inherit'
            }}
            value={data.text ?? ''}
            onChange={(e) => handleTextChange(frame.id, e.target.value)}
            onBlur={handleTextBlur}
            placeholder={frame.placeholder}
          />
        </Box>
      );
    }
    // Frame type
    const getBorderRadius = () => {
      if (frame.shape === 'circle') return '50%';
      if (frame.shape === 'heart') return '0';
      return 8;
    };
    const getClipPath = () => {
      if (frame.shape === 'heart') {
        return 'polygon(50% 0%, 100% 35%, 100% 70%, 50% 100%, 0% 70%, 0% 35%)';
      }
      return 'none';
    };
    return (
      <Box
        key={frame.id}
        onDragOver={(e) => { e.preventDefault(); dropTargetRef.current = frame.id; }}
        onDrop={(e) => {
          e.preventDefault();
          const imageUrl = e.dataTransfer.getData('imageUrl');
          if (imageUrl) handleDropImage(frame.id, imageUrl);
        }}
        sx={{
          ...style,
          border: `3px solid ${frame.borderColor || '#333'}`,
          borderRadius: getBorderRadius(),
          clipPath: getClipPath(),
          backgroundColor: data.image ? 'transparent' : '#f9f9f9',
          backgroundImage: data.image ? `url(${data.image})` : 'none',
          backgroundSize: 'cover',
          backgroundPosition: 'center',
          cursor: 'pointer',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          overflow: 'hidden',
          transition: 'all 0.2s',
          '&:hover': { opacity: 0.9, boxShadow: 3 }
        }}
        onClick={() => {
          const input = document.createElement('input');
          input.type = 'file';
          input.accept = 'image/*';
          input.onchange = (e) => handleImageUpload(frame.id, e);
          input.click();
        }}
      >
        {!data.image && (
          <Box sx={{ textAlign: 'center', color: '#999' }}>
            <ImageIcon sx={{ fontSize: 20 }} />
            <Typography variant="caption" display="block">Add Photo</Typography>
          </Box>
        )}
      </Box>
    );
  };
  return (
    <Box sx={{ display: 'flex', height: 'calc(100vh - 80px)', bgcolor: '#f0f2f5' }}>
      {/* Left Sidebar */}
      <Paper sx={{ width: 280, display: 'flex', flexDirection: 'column', borderRadius: 0 }}>
        <Tabs value={leftTab} onChange={(e, v) => setLeftTab(v)} variant="fullWidth">
          <Tab label="Templates" sx={{ fontSize: '0.75rem' }} />
          <Tab label="Images" sx={{ fontSize: '0.75rem' }} />
        </Tabs>
        {leftTab === 0 && (
          <Box sx={{ flex: 1, overflow: 'auto', p: 1 }}>
            <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 0.5, mb: 1 }}>
              {CATEGORIES.map(cat => (
                <Chip
                  key={cat.name}
                  icon={cat.icon}
                  label={cat.name}
                  size="small"
                  onClick={() => setActiveCategory(cat.name)}
                  color={activeCategory === cat.name ? 'primary' : 'default'}
                  variant={activeCategory === cat.name ? 'filled' : 'outlined'}
                  sx={{ fontSize: '0.6rem' }}
                />
              ))}
            </Box>
            <Grid container spacing={1}>
              {filteredTemplates.map(template => (
                <Grid item xs={6} key={template.id}>
                  <Card
                    sx={{
                      cursor: 'pointer',
                      border: selectedTemplate?.id === template.id ? '2px solid #1976d2' : '1px solid #e0e0e0',
                      position: 'relative',
                      '&:hover': { boxShadow: 3 },
                      '&:hover .template-actions': { opacity: 1 }
                    }}
                    onClick={() => handleSelectTemplate(template)}
                  >
                    <Box sx={{ height: 60, background: template.bgGradient || template.bgColor, position: 'relative' }}>
                      {template.frames?.filter(f => f.type === 'frame').slice(0, 3).map((f, i) => (
                        <Box
                          key={i}
                          sx={{
                            position: 'absolute',
                            left: `${f.x}%`,
                            top: `${f.y}%`,
                            width: `${f.width}%`,
                            height: `${f.height}%`,
                            border: `1px solid ${f.borderColor || '#333'}`,
                            borderRadius: f.shape === 'circle' ? '50%' : 1,
                            backgroundColor: 'rgba(255,255,255,0.7)'
                          }}
                        />
                      ))}
                    </Box>
                    <CardContent sx={{ p: 0.5, '&:last-child': { pb: 0.5 } }}>
                      <Typography variant="caption" noWrap sx={{ fontSize: '0.65rem' }}>
                        {template.name} {template.isCustom && '⭐'}
                      </Typography>
                    </CardContent>
                    {/* Edit/Delete buttons for custom templates and saved designs */}
                    {(template.isCustom || template.isSaved) && (
                      <Box className="template-actions" sx={{ position: 'absolute', top: 2, right: 2, opacity: 0, transition: 'opacity 0.2s', display: 'flex', gap: 0.25 }}>
                        {template.isSaved && (
                          <IconButton size="small" sx={{ backgroundColor: 'rgba(255,255,255,0.9)', p: 0.25 }}
                            onClick={(e) => { e.stopPropagation(); handleEditSaved(template.savedData); }}>
                            <EditIcon sx={{ fontSize: 14 }} />
                          </IconButton>
                        )}
                        <IconButton size="small" sx={{ backgroundColor: 'rgba(255,255,255,0.9)', p: 0.25 }}
                          onClick={(e) => { e.stopPropagation(); 
                            template.isSaved ? handleDeleteSaved(template.savedData.id) : handleDeleteCustomTemplate(template.id); }}>
                          <DeleteIcon sx={{ fontSize: 14 }} />
                        </IconButton>
                      </Box>
                    )}
                  </Card>
                </Grid>
              ))}
            </Grid>
          </Box>
        )}
        {leftTab === 1 && (
          <Box sx={{ flex: 1, overflow: 'auto', p: 1 }}>
            <Typography variant="caption" color="text.secondary" sx={{ mb: 1, display: 'block' }}>
              Drag images to frames
            </Typography>
            <Grid container spacing={1}>
              {SAMPLE_IMAGES.map((img, idx) => (
                <Grid item xs={4} key={idx}>
                  <Box
                    component="img"
                    src={img}
                    draggable
                    onDragStart={(e) => e.dataTransfer.setData('imageUrl', img)}
                    sx={{
                      width: '100%',
                      height: 60,
                      objectFit: 'cover',
                      borderRadius: 1,
                      cursor: 'grab',
                      '&:hover': { opacity: 0.8 }
                    }}
                  />
                </Grid>
              ))}
            </Grid>
          </Box>
        )}
      </Paper>
      {/* Main Canvas */}
      <Box sx={{ flex: 1, display: 'flex', flexDirection: 'column' }}>
        <Paper sx={{ p: 1, borderRadius: 0, display: 'flex', alignItems: 'center', gap: 1, flexWrap: 'wrap' }}>
          <Tooltip title="Undo"><span><IconButton onClick={handleUndo} disabled={historyIndex <= 0} size="small"><UndoIcon /></IconButton></span></Tooltip>
          <Tooltip title="Redo"><span><IconButton onClick={handleRedo} disabled={historyIndex >= history.length - 1} size="small"><RedoIcon /></IconButton></span></Tooltip>
          <Divider orientation="vertical" flexItem />
          <Tooltip title="Zoom Out"><IconButton onClick={() => setZoom(Math.max(50, zoom - 10))} size="small"><ZoomOutIcon /></IconButton></Tooltip>
          <Typography sx={{ minWidth: 45, textAlign: 'center', fontSize: '0.8rem' }}>{zoom}%</Typography>
          <Tooltip title="Zoom In"><IconButton onClick={() => setZoom(Math.min(200, zoom + 10))} size="small"><ZoomInIcon /></IconButton></Tooltip>
          <Divider orientation="vertical" flexItem />
          <Button size="small" startIcon={<SaveIcon />} onClick={() => setSaveDialog(true)} disabled={!selectedTemplate}>Save</Button>
          <Button size="small" startIcon={<LoadIcon />} onClick={() => setLoadDialog(true)}>Load</Button>
          <Button size="small" startIcon={<DownloadIcon />} onClick={handleExport} disabled={!selectedTemplate}>Export</Button>
          <Button size="small" startIcon={<PrintIcon />} onClick={() => window.print()} disabled={!selectedTemplate}>Print</Button>
        </Paper>
        <Box sx={{ flex: 1, overflow: 'auto', display: 'flex', justifyContent: 'center', alignItems: 'center', p: 2 }}>
          {selectedTemplate ? (
            <Paper
              ref={canvasRef}
              sx={{
                width: 500 * (zoom / 100),
                height: 600 * (zoom / 100),
                position: 'relative',
                background: selectedTemplate.bgGradient || selectedTemplate.bgColor,
                boxShadow: 3
              }}
            >
              {selectedTemplate.frames?.map(frame => renderFrame(frame))}
            </Paper>
          ) : (
            <Box sx={{ textAlign: 'center', color: '#999' }}>
              <Typography variant="h6">Select a template to get started</Typography>
              <Typography variant="body2">Choose from {STORY_TEMPLATES.length} story templates</Typography>
            </Box>
          )}
        </Box>
      </Box>
      {/* Save Dialog */}
      <Dialog open={saveDialog} onClose={() => setSaveDialog(false)}>
        <DialogTitle>Save Story</DialogTitle>
        <DialogContent>
          <TextField
            autoFocus
            margin="dense"
            label="Name"
            fullWidth
            value={storyName}
            onChange={(e) => setStoryName(e.target.value)}
            placeholder="e.g., Summer Vacation 2024"
          />
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setSaveDialog(false)}>Cancel</Button>
          <Button onClick={handleSaveAsTemplate} variant="outlined">Save as Template</Button>
          <Button onClick={handleSave} variant="contained">Save Story</Button>
        </DialogActions>
      </Dialog>
      <Snackbar open={snackbar.open} autoHideDuration={3000} onClose={() => setSnackbar({ ...snackbar, open: false })}>
        <Alert severity={snackbar.severity}>{snackbar.message}</Alert>
      </Snackbar>
    </Box>
  );
};
export default StoryMaker;
