import React, { useState, useEffect, useCallback } from 'react';
import {
  Box,
  Paper,
  Typography,
  Button,
  Grid,
  Card,
  CardContent,
  CardActions,
  CardMedia,
  TextField,
  Select,
  MenuItem,
  FormControl,
  InputLabel,
  Chip,
  IconButton,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  CircularProgress,
  Alert,
  Snackbar,
  Tabs,
  Tab,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  LinearProgress,
  Divider,
  List,
  ListItem,
  ListItemIcon,
  ListItemText,
  Collapse
} from '@mui/material';
import {
  CloudUpload as UploadIcon,
  Delete as DeleteIcon,
  Add as AddIcon,
  School as SchoolIcon,
  Work as WorkIcon,
  Games as GamesIcon,
  Print as PrintIcon,
  Build as BuildIcon,
  Info as InfoIcon,
  ExpandLess,
  ExpandMore,
  Refresh as RefreshIcon,
  People as PeopleIcon,
  Business as BusinessIcon,
  Image as ImageIcon
} from '@mui/icons-material';
import { useSelector } from 'react-redux';
import axios from 'axios';
const BACKEND_URL = process.env.REACT_APP_BACKEND_URL;
// Tab Panel Component
function TabPanel({ children, value, index, ...other }) {
  return (
    <div role="tabpanel" hidden={value !== index} {...other}>
      {value === index && <Box sx={{ p: 3 }}>{children}</Box>}
    </div>
  );
}
// Category Icons
const categoryIcons = {
  'ACADEMIC': <SchoolIcon />,
  'EARLY-CAREER': <WorkIcon />,
  'EDUTAINMENT': <GamesIcon />,
  'PRINT-RICH': <PrintIcon />,
  'MAKER': <BuildIcon />,
  'INFO-HUB': <InfoIcon />
};
const AdminPanel = () => {
  const { accessToken, userRole } = useSelector((state) => state.login);
  const [tabValue, setTabValue] = useState(0);
  const [categories, setCategories] = useState([]);
  const [selectedCategory, setSelectedCategory] = useState('');
  const [selectedSubcategory, setSelectedSubcategory] = useState('');
  const [images, setImages] = useState([]);
  const [loading, setLoading] = useState(false);
  const [uploading, setUploading] = useState(false);
  const [stats, setStats] = useState({});
  const [schools, setSchools] = useState([]);
  const [expandedCategory, setExpandedCategory] = useState('');
  // Upload form state
  const [uploadFile, setUploadFile] = useState(null);
  const [uploadTitle, setUploadTitle] = useState('');
  const [uploadDescription, setUploadDescription] = useState('');
  const [uploadTags, setUploadTags] = useState('');
  const [uploadDialogOpen, setUploadDialogOpen] = useState(false);
  // School form state
  const [schoolDialogOpen, setSchoolDialogOpen] = useState(false);
  const [schoolForm, setSchoolForm] = useState({
    name: '',
    adminEmail: '',
    adminName: '',
    adminPhone: '',
    city: '',
    state: ''
  });
  // Bulk upload state
  const [bulkUploadDialogOpen, setBulkUploadDialogOpen] = useState(false);
  const [bulkUploadType, setBulkUploadType] = useState(''); // 'schools' or 'users'
  const [bulkUploadFile, setBulkUploadFile] = useState(null);
  const [bulkUploading, setBulkUploading] = useState(false);
  const [bulkUploadResults, setBulkUploadResults] = useState(null);
  // Snackbar
  const [snackbar, setSnackbar] = useState({ open: false, message: '', severity: 'success' });
  // Fetch categories
  const fetchCategories = useCallback(async () => {
    try {
      const response = await axios.get(`${BACKEND_URL}/api/admin/categories`, {
        headers: { Authorization: `Bearer ${accessToken}` }
      });
      setCategories(response.data.categories);
    } catch (error) {
      console.error('Error fetching categories:', error);
    }
  }, [accessToken]);
  // Fetch dashboard stats
  const fetchStats = useCallback(async () => {
    try {
      const response = await axios.get(`${BACKEND_URL}/api/admin/dashboard-stats`, {
        headers: { Authorization: `Bearer ${accessToken}` }
      });
      setStats(response.data);
    } catch (error) {
      console.error('Error fetching stats:', error);
    }
  }, [accessToken]);
  // Fetch schools (for super admin)
  const fetchSchools = useCallback(async () => {
    if (userRole !== 'SUPER_ADMIN') return;
    try {
      const response = await axios.get(`${BACKEND_URL}/api/rest/schools/list`, {
        headers: { Authorization: `Bearer ${accessToken}` }
      });
      setSchools(response.data.data);
    } catch (error) {
      console.error('Error fetching schools:', error);
    }
  }, [accessToken, userRole]);
  // Fetch images
  const fetchImages = useCallback(async () => {
    setLoading(true);
    try {
      let url = `${BACKEND_URL}/api/admin/images?`;
      if (selectedCategory) url += `category=${selectedCategory}&`;
      if (selectedSubcategory) url += `subcategory=${selectedSubcategory}&`;
      const response = await axios.get(url, {
        headers: { Authorization: `Bearer ${accessToken}` }
      });
      setImages(response.data.images);
    } catch (error) {
      console.error('Error fetching images:', error);
    }
    setLoading(false);
  }, [accessToken, selectedCategory, selectedSubcategory]);
  useEffect(() => {
    fetchCategories();
    fetchStats();
    fetchSchools();
  }, [fetchCategories, fetchStats, fetchSchools]);
  useEffect(() => {
    fetchImages();
  }, [fetchImages]);
  // Handle file upload
  const handleUpload = async () => {
    if (!uploadFile || !selectedCategory || !uploadTitle) {
      setSnackbar({ open: true, message: 'Please fill all required fields', severity: 'error' });
      return;
    }
    setUploading(true);
    const formData = new FormData();
    formData.append('file', uploadFile);
    formData.append('category', selectedCategory);
    formData.append('subcategory', selectedSubcategory || '');
    formData.append('title', uploadTitle);
    formData.append('description', uploadDescription);
    formData.append('tags', uploadTags);
    try {
      await axios.post(`${BACKEND_URL}/api/admin/upload-image`, formData, {
        headers: {
          Authorization: `Bearer ${accessToken}`,
          'Content-Type': 'multipart/form-data'
        }
      });
      setSnackbar({ open: true, message: 'Image uploaded successfully!', severity: 'success' });
      setUploadDialogOpen(false);
      resetUploadForm();
      fetchImages();
      fetchCategories();
    } catch (error) {
      setSnackbar({ open: true, message: error.response?.data?.detail || 'Upload failed', severity: 'error' });
    }
    setUploading(false);
  };
  // Handle image delete
  const handleDelete = async (imageId) => {
    if (!window.confirm('Are you sure you want to delete this image?')) return;
    try {
      await axios.delete(`${BACKEND_URL}/api/admin/images/${imageId}`, {
        headers: { Authorization: `Bearer ${accessToken}` }
      });
      setSnackbar({ open: true, message: 'Image deleted successfully!', severity: 'success' });
      fetchImages();
      fetchCategories();
    } catch (error) {
      setSnackbar({ open: true, message: 'Delete failed', severity: 'error' });
    }
  };
  // Handle school creation
  const handleCreateSchool = async () => {
    try {
      await axios.post(`${BACKEND_URL}/api/rest/schools/create`, schoolForm, {
        headers: { Authorization: `Bearer ${accessToken}` }
      });
      setSnackbar({ open: true, message: 'School created! Admin credentials sent via email.', severity: 'success' });
      setSchoolDialogOpen(false);
      setSchoolForm({ name: '', adminEmail: '', adminName: '', adminPhone: '', city: '', state: '' });
      fetchSchools();
      fetchStats();
    } catch (error) {
      setSnackbar({ open: true, message: error.response?.data?.detail || 'Creation failed', severity: 'error' });
    }
  };
  const resetUploadForm = () => {
    setUploadFile(null);
    setUploadTitle('');
    setUploadDescription('');
    setUploadTags('');
  };
  // Bulk upload handler
  const handleBulkUpload = async () => {
    if (!bulkUploadFile) {
      setSnackbar({ open: true, message: 'Please select a file', severity: 'error' });
      return;
    }
    setBulkUploading(true);
    setBulkUploadResults(null);
    try {
      const formData = new FormData();
      formData.append('file', bulkUploadFile);
      const endpoint = bulkUploadType === 'schools' 
        ? `${BACKEND_URL}/api/admin/bulk-upload/schools`
        : `${BACKEND_URL}/api/admin/bulk-upload/users`;
      const response = await axios.post(endpoint, formData, {
        headers: { 
          Authorization: `Bearer ${accessToken}`,
          'Content-Type': 'multipart/form-data'
        }
      });
      setBulkUploadResults(response.data);
      setSnackbar({ 
        open: true, 
        message: `Successfully created ${response.data.created} out of ${response.data.total}`, 
        severity: response.data.failed > 0 ? 'warning' : 'success' 
      });
      // Refresh data
      if (bulkUploadType === 'schools') {
        fetchSchools();
      }
      fetchStats();
    } catch (error) {
      console.error('Bulk upload error:', error);
      setSnackbar({ 
        open: true, 
        message: error.response?.data?.detail || 'Bulk upload failed', 
        severity: 'error' 
      });
    }
    setBulkUploading(false);
  };
  const openBulkUploadDialog = (type) => {
    setBulkUploadType(type);
    setBulkUploadFile(null);
    setBulkUploadResults(null);
    setBulkUploadDialogOpen(true);
  };
  const handleTabChange = (event, newValue) => {
    setTabValue(newValue);
  };
  return (
    <Box sx={{ p: 3, bgcolor: '#f5f5f5', minHeight: '100vh' }}>
      <Typography variant="h4" gutterBottom sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
        🎛️ Admin Panel
        {userRole === 'SUPER_ADMIN' && <Chip label="Super Admin" color="primary" size="small" />}
      </Typography>
      {/* Stats Cards */}
      <Grid container spacing={3} sx={{ mb: 3 }}>
        <Grid item xs={12} sm={6} md={3}>
          <Card sx={{ bgcolor: '#e3f2fd' }}>
            <CardContent>
              <Typography variant="h3">{stats.totalImages || 0}</Typography>
              <Typography color="text.secondary">Total Images</Typography>
            </CardContent>
          </Card>
        </Grid>
        <Grid item xs={12} sm={6} md={3}>
          <Card sx={{ bgcolor: '#e8f5e9' }}>
            <CardContent>
              <Typography variant="h3">{stats.totalUsers || 0}</Typography>
              <Typography color="text.secondary">Total Users</Typography>
            </CardContent>
          </Card>
        </Grid>
        <Grid item xs={12} sm={6} md={3}>
          <Card sx={{ bgcolor: '#fff3e0' }}>
            <CardContent>
              <Typography variant="h3">{stats.totalStudents || 0}</Typography>
              <Typography color="text.secondary">Students</Typography>
            </CardContent>
          </Card>
        </Grid>
        <Grid item xs={12} sm={6} md={3}>
          <Card sx={{ bgcolor: '#fce4ec' }}>
            <CardContent>
              <Typography variant="h3">{stats.totalTeachers || 0}</Typography>
              <Typography color="text.secondary">Teachers</Typography>
            </CardContent>
          </Card>
        </Grid>
      </Grid>
      <Paper sx={{ width: '100%' }}>
        <Tabs value={tabValue} onChange={handleTabChange} sx={{ borderBottom: 1, borderColor: 'divider' }}>
          <Tab icon={<ImageIcon />} label="Image Management" />
          {userRole === 'SUPER_ADMIN' && <Tab icon={<BusinessIcon />} label="Schools" />}
          <Tab icon={<PeopleIcon />} label="Users" />
        </Tabs>
        {/* Image Management Tab */}
        <TabPanel value={tabValue} index={0}>
          <Grid container spacing={3}>
            {/* Categories Sidebar */}
            <Grid item xs={12} md={3}>
              <Paper sx={{ p: 2 }}>
                <Typography variant="h6" gutterBottom>Categories</Typography>
                <List>
                  {categories.map((cat) => (
                    <React.Fragment key={cat.id}>
                      <ListItem 
                        button 
                        onClick={() => {
                          setSelectedCategory(cat.id);
                          setSelectedSubcategory('');
                          setExpandedCategory(expandedCategory === cat.id ? '' : cat.id);
                        }}
                        selected={selectedCategory === cat.id && !selectedSubcategory}
                      >
                        <ListItemIcon>{categoryIcons[cat.id]}</ListItemIcon>
                        <ListItemText 
                          primary={cat.name} 
                          secondary={`${cat.imageCount} images`}
                        />
                        {cat.subcategories?.length > 0 && (
                          expandedCategory === cat.id ? <ExpandLess /> : <ExpandMore />
                        )}
                      </ListItem>
                      <Collapse in={expandedCategory === cat.id} timeout="auto" unmountOnExit>
                        <List component="div" disablePadding>
                          {cat.subcategories?.map((sub) => (
                            <ListItem 
                              button 
                              key={sub.id}
                              sx={{ pl: 4 }}
                              selected={selectedSubcategory === sub.id}
                              onClick={() => {
                                setSelectedCategory(cat.id);
                                setSelectedSubcategory(sub.id);
                              }}
                            >
                              <ListItemText 
                                primary={sub.name}
                                secondary={`${sub.imageCount} images`}
                              />
                            </ListItem>
                          ))}
                        </List>
                      </Collapse>
                    </React.Fragment>
                  ))}
                </List>
              </Paper>
            </Grid>
            {/* Images Grid */}
            <Grid item xs={12} md={9}>
              <Box sx={{ display: 'flex', justifyContent: 'space-between', mb: 2 }}>
                <Typography variant="h6">
                  {selectedCategory ? `${selectedCategory}${selectedSubcategory ? ` / ${selectedSubcategory}` : ''}` : 'All Images'}
                </Typography>
                <Box>
                  <Button 
                    startIcon={<RefreshIcon />} 
                    onClick={fetchImages}
                    sx={{ mr: 1 }}
                  >
                    Refresh
                  </Button>
                  <Button 
                    variant="contained" 
                    startIcon={<UploadIcon />}
                    onClick={() => setUploadDialogOpen(true)}
                  >
                    Upload Image
                  </Button>
                </Box>
              </Box>
              {loading && <LinearProgress sx={{ mb: 2 }} />}
              <Grid container spacing={2}>
                {images.length === 0 && !loading && (
                  <Grid item xs={12}>
                    <Alert severity="info">
                      No images found. {!selectedCategory && 'Select a category to view images.'}
                    </Alert>
                  </Grid>
                )}
                {images.map((image) => (
                  <Grid item xs={12} sm={6} md={4} lg={3} key={image.id}>
                    <Card>
                      <CardMedia
                        component="img"
                        height="140"
                        image={image.url?.startsWith('http') ? image.url : `${BACKEND_URL}${image.url}`}
                        alt={image.title}
                        sx={{ objectFit: 'cover' }}
                        onError={(e) => { e.target.src = 'https://via.placeholder.com/300x140?text=No+Image'; }}
                      />
                      <CardContent sx={{ py: 1 }}>
                        <Typography variant="subtitle2" noWrap>{image.title}</Typography>
                        <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 0.5, mt: 1 }}>
                          {image.tags?.slice(0, 3).map((tag, i) => (
                            <Chip key={i} label={tag} size="small" variant="outlined" />
                          ))}
                        </Box>
                      </CardContent>
                      <CardActions>
                        <IconButton color="error" size="small" onClick={() => handleDelete(image.id)}>
                          <DeleteIcon />
                        </IconButton>
                      </CardActions>
                    </Card>
                  </Grid>
                ))}
              </Grid>
            </Grid>
          </Grid>
        </TabPanel>
        {/* Schools Tab (Super Admin Only) */}
        {userRole === 'SUPER_ADMIN' && (
          <TabPanel value={tabValue} index={1}>
            <Box sx={{ display: 'flex', justifyContent: 'space-between', mb: 2 }}>
              <Typography variant="h6">Schools ({schools.length})</Typography>
              <Box>
                <Button 
                  variant="outlined" 
                  startIcon={<UploadIcon />}
                  onClick={() => openBulkUploadDialog('schools')}
                  sx={{ mr: 1 }}
                >
                  Bulk Upload Schools
                </Button>
                <Button 
                  variant="contained" 
                  startIcon={<AddIcon />}
                  onClick={() => setSchoolDialogOpen(true)}
                >
                  Add School
                </Button>
              </Box>
            </Box>
            <TableContainer component={Paper}>
              <Table>
                <TableHead>
                  <TableRow sx={{ bgcolor: '#f5f5f5' }}>
                    <TableCell>School Code</TableCell>
                    <TableCell>Name</TableCell>
                    <TableCell>City</TableCell>
                    <TableCell>Status</TableCell>
                    <TableCell>Created</TableCell>
                  </TableRow>
                </TableHead>
                <TableBody>
                  {schools.map((inst) => (
                    <TableRow key={inst.id}>
                      <TableCell><Chip label={inst.code} size="small" /></TableCell>
                      <TableCell>{inst.name}</TableCell>
                      <TableCell>{inst.city || '-'}</TableCell>
                      <TableCell>
                        <Chip 
                          label={inst.is_active ? 'Active' : 'Inactive'} 
                          color={inst.is_active ? 'success' : 'error'}
                          size="small"
                        />
                      </TableCell>
                      <TableCell>{new Date(inst.created_at).toLocaleDateString()}</TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </TableContainer>
          </TabPanel>
        )}
        {/* Users Tab */}
        <TabPanel value={tabValue} index={userRole === 'SUPER_ADMIN' ? 2 : 1}>
          <Box sx={{ display: 'flex', justifyContent: 'space-between', mb: 2 }}>
            <Typography variant="h6">Bulk User Management</Typography>
            <Button 
              variant="contained" 
              startIcon={<UploadIcon />}
              onClick={() => openBulkUploadDialog('users')}
            >
              Bulk Upload Users
            </Button>
          </Box>
          <Alert severity="info" sx={{ mb: 2 }}>
            Upload an Excel or CSV file with user details. Required columns: <strong>email</strong>, <strong>role</strong> (TEACHER/STUDENT/PARENT).
            {userRole === 'SUPER_ADMIN' && <> Super Admin must also include <strong>school_code</strong> column.</>}
          </Alert>
          <Typography variant="body2" color="text.secondary">
            Individual user management is available in the sidebar. Navigate to Students/Teachers sections.
          </Typography>
        </TabPanel>
      </Paper>
      {/* Upload Dialog */}
      <Dialog open={uploadDialogOpen} onClose={() => setUploadDialogOpen(false)} maxWidth="sm" fullWidth>
        <DialogTitle>Upload Image</DialogTitle>
        <DialogContent>
          <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2, mt: 1 }}>
            <FormControl fullWidth>
              <InputLabel>Category *</InputLabel>
              <Select
                value={selectedCategory}
                label="Category *"
                onChange={(e) => {
                  setSelectedCategory(e.target.value);
                  setSelectedSubcategory('');
                }}
              >
                {categories.map((cat) => (
                  <MenuItem key={cat.id} value={cat.id}>{cat.name}</MenuItem>
                ))}
              </Select>
            </FormControl>
            {selectedCategory && (
              <FormControl fullWidth>
                <InputLabel>Subcategory</InputLabel>
                <Select
                  value={selectedSubcategory}
                  label="Subcategory"
                  onChange={(e) => setSelectedSubcategory(e.target.value)}
                >
                  <MenuItem value="">None</MenuItem>
                  {categories.find(c => c.id === selectedCategory)?.subcategories?.map((sub) => (
                    <MenuItem key={sub.id} value={sub.id}>{sub.name}</MenuItem>
                  ))}
                </Select>
              </FormControl>
            )}
            <TextField
              label="Title *"
              value={uploadTitle}
              onChange={(e) => setUploadTitle(e.target.value)}
              fullWidth
            />
            <TextField
              label="Description"
              value={uploadDescription}
              onChange={(e) => setUploadDescription(e.target.value)}
              fullWidth
              multiline
              rows={2}
            />
            <TextField
              label="Tags (comma-separated)"
              value={uploadTags}
              onChange={(e) => setUploadTags(e.target.value)}
              fullWidth
              placeholder="math, science, class-10"
            />
            <Button
              variant="outlined"
              component="label"
              startIcon={<UploadIcon />}
              fullWidth
            >
              {uploadFile ? uploadFile.name : 'Choose File *'}
              <input
                type="file"
                hidden
                accept="image/*,application/pdf"
                onChange={(e) => setUploadFile(e.target.files[0])}
              />
            </Button>
          </Box>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setUploadDialogOpen(false)}>Cancel</Button>
          <Button 
            onClick={handleUpload} 
            variant="contained" 
            disabled={uploading}
            startIcon={uploading && <CircularProgress size={20} />}
          >
            {uploading ? 'Uploading...' : 'Upload'}
          </Button>
        </DialogActions>
      </Dialog>
      {/* School Dialog */}
      <Dialog open={schoolDialogOpen} onClose={() => setSchoolDialogOpen(false)} maxWidth="sm" fullWidth>
        <DialogTitle>Create New School</DialogTitle>
        <DialogContent>
          <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2, mt: 1 }}>
            <TextField
              label="School Name *"
              value={schoolForm.name}
              onChange={(e) => setSchoolForm({...schoolForm, name: e.target.value})}
              fullWidth
            />
            <Divider><Chip label="Admin Details" size="small" /></Divider>
            <TextField
              label="Admin Name *"
              value={schoolForm.adminName}
              onChange={(e) => setSchoolForm({...schoolForm, adminName: e.target.value})}
              fullWidth
            />
            <TextField
              label="Admin Email *"
              type="email"
              value={schoolForm.adminEmail}
              onChange={(e) => setSchoolForm({...schoolForm, adminEmail: e.target.value})}
              fullWidth
              helperText="Auto-generated password will be sent to this email"
            />
            <TextField
              label="Admin Phone"
              value={schoolForm.adminPhone}
              onChange={(e) => setSchoolForm({...schoolForm, adminPhone: e.target.value})}
              fullWidth
            />
            <Divider><Chip label="Location" size="small" /></Divider>
            <Grid container spacing={2}>
              <Grid item xs={6}>
                <TextField
                  label="City"
                  value={schoolForm.city}
                  onChange={(e) => setSchoolForm({...schoolForm, city: e.target.value})}
                  fullWidth
                />
              </Grid>
              <Grid item xs={6}>
                <TextField
                  label="State"
                  value={schoolForm.state}
                  onChange={(e) => setSchoolForm({...schoolForm, state: e.target.value})}
                  fullWidth
                />
              </Grid>
            </Grid>
          </Box>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setSchoolDialogOpen(false)}>Cancel</Button>
          <Button 
            onClick={handleCreateSchool} 
            variant="contained"
            disabled={!schoolForm.name || !schoolForm.adminEmail || !schoolForm.adminName}
          >
            Create School
          </Button>
        </DialogActions>
      </Dialog>
      {/* Bulk Upload Dialog */}
      <Dialog open={bulkUploadDialogOpen} onClose={() => setBulkUploadDialogOpen(false)} maxWidth="md" fullWidth>
        <DialogTitle>
          Bulk Upload {bulkUploadType === 'schools' ? 'Schools' : 'Users'}
        </DialogTitle>
        <DialogContent>
          <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2, mt: 1 }}>
            <Alert severity="info">
              {bulkUploadType === 'schools' ? (
                <>
                  <strong>Required columns:</strong> school_name, admin_email<br/>
                  <strong>Optional columns:</strong> admin_name, address, city, state
                </>
              ) : (
                <>
                  <strong>Required columns:</strong> email, role (TEACHER/STUDENT/PARENT)
                  {userRole === 'SUPER_ADMIN' && <>, school_code</>}<br/>
                  <strong>Optional columns:</strong> name, phone, address, city, state
                </>
              )}
            </Alert>
            <Button
              variant="outlined"
              component="label"
              startIcon={<UploadIcon />}
              fullWidth
              sx={{ py: 2 }}
            >
              {bulkUploadFile ? bulkUploadFile.name : 'Choose Excel or CSV File'}
              <input
                type="file"
                hidden
                accept=".xlsx,.xls,.csv"
                onChange={(e) => {
                  setBulkUploadFile(e.target.files[0]);
                  setBulkUploadResults(null);
                }}
              />
            </Button>
            {bulkUploadResults && (
              <Paper sx={{ p: 2, bgcolor: bulkUploadResults.failed > 0 ? '#fff3e0' : '#e8f5e9' }}>
                <Typography variant="h6" gutterBottom>Upload Results</Typography>
                <Grid container spacing={2}>
                  <Grid item xs={4}>
                    <Typography variant="h4" color="primary">{bulkUploadResults.total}</Typography>
                    <Typography variant="body2">Total Rows</Typography>
                  </Grid>
                  <Grid item xs={4}>
                    <Typography variant="h4" color="success.main">{bulkUploadResults.created}</Typography>
                    <Typography variant="body2">Created</Typography>
                  </Grid>
                  <Grid item xs={4}>
                    <Typography variant="h4" color="error.main">{bulkUploadResults.failed}</Typography>
                    <Typography variant="body2">Failed</Typography>
                  </Grid>
                </Grid>
                {bulkUploadResults.errors?.length > 0 && (
                  <Box sx={{ mt: 2, maxHeight: 150, overflow: 'auto' }}>
                    <Typography variant="subtitle2" color="error">Errors:</Typography>
                    {bulkUploadResults.errors.slice(0, 10).map((err, i) => (
                      <Typography key={i} variant="body2" color="text.secondary">• {err}</Typography>
                    ))}
                    {bulkUploadResults.errors.length > 10 && (
                      <Typography variant="body2" color="text.secondary">
                        ... and {bulkUploadResults.errors.length - 10} more errors
                      </Typography>
                    )}
                  </Box>
                )}
              </Paper>
            )}
          </Box>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setBulkUploadDialogOpen(false)}>Close</Button>
          <Button 
            onClick={handleBulkUpload} 
            variant="contained" 
            disabled={!bulkUploadFile || bulkUploading}
            startIcon={bulkUploading && <CircularProgress size={20} />}
          >
            {bulkUploading ? 'Uploading...' : 'Upload & Process'}
          </Button>
        </DialogActions>
      </Dialog>
      {/* Snackbar */}
      <Snackbar
        open={snackbar.open}
        autoHideDuration={6000}
        onClose={() => setSnackbar({...snackbar, open: false})}
      >
        <Alert severity={snackbar.severity} onClose={() => setSnackbar({...snackbar, open: false})}>
          {snackbar.message}
        </Alert>
      </Snackbar>
    </Box>
  );
};
export default AdminPanel;
