import React, { useState } from 'react'
import { TextField, InputAdornment, FormHelperText } from '@mui/material'

// Validation patterns
const validationPatterns = {
    name: /^[a-zA-Z\s]+$/,
    principalName: /^[a-zA-Z\s]+$/,
    schoolName: /^[a-zA-Z0-9\s]+$/,
    mobileNumber: /^(\+91)?[6-9]\d{9}$/,
    postalCode: /^\d{6}$/,
};

const maxLengths = {
    name: 100,
    principalName: 100,
    schoolName: 150,
    mobileNumber: 13,
    postalCode: 6,
    address: 200,
    city: 50,
    state: 50,
};

const MSTextField = (props) => {
    const [error, setError] = useState('');
    
    const validateField = (value, fieldName) => {
        if (!value) return '';
        
        // Check max length
        const maxLen = maxLengths[fieldName];
        if (maxLen && value.length > maxLen) {
            return `Maximum ${maxLen} characters allowed`;
        }
        
        // Check pattern for specific fields - only validate name fields for special chars
        if (['name', 'principalName'].includes(fieldName)) {
            if (!/^[a-zA-Z\s]+$/.test(value)) {
                return 'Only letters and spaces allowed';
            }
        }
        
        // Validate mobile number format
        if (fieldName === 'mobileNumber' && value.length > 5) {
            const cleanNumber = value.replace(/[\s-]/g, '');
            if (!/^(\+91)?[6-9]\d{9}$/.test(cleanNumber)) {
                return 'Invalid mobile number (use +91XXXXXXXXXX format)';
            }
        }
        
        // Validate postal code
        if (fieldName === 'postalCode' && value.length === 6) {
            if (!/^\d{6}$/.test(value)) {
                return 'Postal code must be 6 digits';
            }
        }
        
        return '';
    };
    
    const handleChange = (e) => {
        const value = e.target.value;
        const fieldName = props.fieldName;
        
        // Validate on change
        const errorMsg = validateField(value, fieldName);
        setError(errorMsg);
        
        // Still call parent onChange
        props.onChange(e, fieldName);
    };
    
    return (
        <div style={[{
            display: 'flex',
            flexDirection: 'column'
        }, props.style].reduce((acc, curr) => Object.assign(acc, curr), {})}>
            <label htmlFor={props.id}>{props.label}</label>
            {props.label ? 
            <>
                <TextField 
                    type={props.type} 
                    id={props.id} 
                    disabled={props.disabled}
                    value={props.value} 
                    style={props.style}
                    onChange={handleChange}
                    error={!!error}
                    inputProps={{
                        maxLength: maxLengths[props.fieldName] || 200,
                        autoComplete: props.type === 'password' ? 'new-password' : 'off'
                    }}
                    InputProps={{
                        startAdornment: props.fieldName === "schoolCode" || props.fieldName === "teacherCode" ? 
                        <InputAdornment position="start">{props.fieldName === "schoolCode" ? "SC" : "TR"} </InputAdornment> : null 
                    }}
                    sx={{
                        '& input::placeholder': {
                            color: '#aaa',
                            opacity: 0.6,
                            fontStyle: 'italic',
                        },
                    }}
                    fullWidth 
                    placeholder={props.placeholder} 
                    size='small' 
                />
                {error && <FormHelperText error>{error}</FormHelperText>}
            </> : null }
        </div>
    )
}
export default MSTextField